; The deck of the Gull's Wager at night, two days out from Questeria: the Prologue's voyage. She lies
; along the map with her bow to the west: the bowsprit and the gilt gull under it, the north rail with
; lanterns swinging on it, the hatch over the hold, the mainmast amidships with its sails furled for
; the night and the crow's nest at the top, crates and rope about, and the wheel at the stern. Her bow
; and stern are blocks on the detail layer; the ground under them is deck where you can stand. Dark,
; with the lanterns lighting it. There's no way off but the end of the Prologue.

[map]
id = gulls-wager
name = The Gull's Wager
tileset = ship
size = 45 27
dark = yes
ambient = 0.35
fog = no
music = Sea

[legend]
~ = sea
- = deck
# = rail-n
= = rail-s
_ = hull
o = hatch
< = bow
> = stern
/ = bowsprit
* = lantern

