[objects]
spawn start 18 10.2 facing=up

; P-04 starts when you walk up to the bow, where the two of you stand and look out at the sea, with a
; red ! over it till then, so you get to walk the deck first.
trigger voyage 11 11 w=3 h=4 talk=p-04 mark=yes

prop mast 22 12.5
prop ship-wheel 32.5 12
prop lantern-hanging 13.5 12.2
prop lantern-hanging 21 15.3
prop lantern-hanging 29.5 15.3
prop rope-coil 15 14.4
prop rope-coil 26.5 10.6
prop cargo-crate 28 14.7
prop cargo-crate 29.3 14.9
prop cargo-barrel 14.6 14.2
prop cargo-barrel 27.4 11.4
prop cargo-barrel 19.6 14.9
prop sacks 17.6 14.4
prop cask 30.6 11
prop bedroll 23.6 14.8

; The lanterns swinging on the rail are tiles, and so are the two painted on the stern, so they light
; the deck with lights of their own.
light rail-lamp-1 19 10 reach=3 strength=0.9
light rail-lamp-2 25 10 reach=3 strength=0.9
light stern-lamp 34.5 11.5 reach=2.5 strength=0.8
light quarter-lamp 34 14 reach=2 strength=0.7

; The captain at the wheel, and the two on watch by the mast.
npc odelle 31 12.6 cast=odelle facing=left say="Two days to Questeria, if the sea behaves.|She creaks like an old aunt, and holds like one too.|Get some sleep. Or don't. The sea's prettier at night."
npc sailor-a 24 9.9 look=146 name="A Deckhand" facing=right say="Two days to port. Two days of beans.|Mind the hatch, it bites ankles.|Captain's in a mood. Captain's always in a mood.|Hear that? No, me neither. That's what worries me."
npc sailor-b 25.5 10.2 look=122 name="A Deckhand" facing=left say="Coil the rope clockwise or the sea gets ideas.|Questeria by Thursday, if the wind likes us.|I've seen wraiths once. Once was plenty."

; P-05's sea-wraiths, up over the port rail when the lookout rings the bell, and gone once they're
; beaten: the tutorial fight. One squeezes in between the barrel and the sacks at the bow, four
; tiles from the two of you, to walk up to and hit first; the other two come over amidships and
; aft, and take a turn or two to get there, so there's one at a time to learn on. The open deck
; between the bow and the hatch is where it's fought.
npc wraith-1 16 14 creature=sea-wraith name="A Sea-wraith" facing=up when=wraiths-sighted unless=wraiths-beaten
npc wraith-2 22 15 creature=sea-wraith name="A Sea-wraith" facing=up when=wraiths-sighted unless=wraiths-beaten
npc wraith-3 25 15 creature=sea-wraith name="A Sea-wraith" facing=left when=wraiths-sighted unless=wraiths-beaten

; What the two of you say on deck before the voyage starts, and the watch talking it over.
trigger bark-deck-night 16 10 w=2 h=5 bark=deck-night
trigger bark-deck-sailors 21 9 w=7 h=3 bark=deck-sailors once=no
